import re
from datetime import timedelta
from pathlib import Path

from logkeep import streams
from logkeep.errors import DataError

BUILTIN = {
    "max_size": None,
    "max_age": None,
    "naming": "numbered",
    "offset": timedelta(0),
    "compress_after": 1,
    "keep": 5,
    "keep_days": None,
}

