DURATION = re.compile(r"([0-9]+)([mhd])\Z")
OFFSET = re.compile(r"([+-])([0-9]{2}):([0-9]{2})\Z")
NUMBER = re.compile(r"[0-9]+\Z")
SECTION = re.compile(r"\[(.*)\]\Z")


def _bad(message):
    return DataError("policy", f"policy.ini: {message}")


def _size(value):
    if value == "off":
        return None
    m = SIZE.match(value)
    if not m:
        raise _bad(f"bad size {value!r}")
    return int(m.group(1)) * {"": 1, "k": 1024, "m": 1024**2, "g": 1024**3}[m.group(2).lower()]


def _duration(value):
    if value == "off":
        return None
    m = DURATION.match(value)
    if not m:
        raise _bad(f"bad duration {value!r}")
    unit = {"m": "minutes", "h": "hours", "d": "days"}[m.group(2)]
    return timedelta(**{unit: int(m.group(1))})


def _naming(value):
    if value not in ("numbered", "dated"):
        raise _bad(f"bad naming {value!r}")
    return value


def _offset(value):
    m = OFFSET.match(value)
    if not m or int(m.group(2)) > 23 or int(m.group(3)) > 59:
        raise _bad(f"bad offset {value!r}")
    delta = timedelta(hours=int(m.group(2)), minutes=int(m.group(3)))
    return -delta if m.group(1) == "-" else delta


def _number(minimum, allow_off=False):
    def parse(value):
        if allow_off and value == "off":
            return None
        if not NUMBER.match(value) or int(value) < minimum:
            raise _bad(f"bad number {value!r}")
        return int(value)

    return parse


PARSERS = {
    "max_size": _size,
    "max_age": _duration,
    "naming": _naming,
    "offset": _offset,
    "compress_after": _number(0),
    "keep": _number(1),
    "keep_days": _number(1, allow_off=True),
}


