            current = sections[key]
            continue
        if current is None or "=" not in line:
            raise _bad(f"bad line {raw!r}")
        name, value = (part.strip() for part in line.split("=", 1))
        if name not in PARSERS:
            raise _bad(f"unknown key {name!r}")
        if name in current:
            raise _bad(f"key {name!r} given twice")
        current[name] = PARSERS[name](value)
    defaults = sections.get(("defaults", None), {})
    per_stream = {key[1]: values for key, values in sections.items() if key[0] == "stream"}
    return per_stream, defaults


def settings(per_stream, defaults, name):
    own = per_stream.get(name, {})
    return {key: own[key] if key in own else defaults.get(key, BUILTIN[key]) for key in BUILTIN}
