"""rotate (docs/rotate.md)."""

import gzip
import re
from datetime import date, datetime, timedelta, timezone

from logkeep import dates, policy, streams
from logkeep.errors import DataError, Refused

OLD_TIME = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2} [0-9]{2}:[0-9]{2}:[0-9]{2}\Z")
DAY = re.compile(r"([0-9]{4}-[0-9]{2}-[0-9]{2})(?:\.([2-9]|[1-9][0-9]+))?\Z")
NUMBER = re.compile(r"[1-9][0-9]*\Z")


def parse_time(value):
    """A time of data.md, section 2, or None."""
    if not isinstance(value, str) or not value.isascii():
        return None
    try:
        if OLD_TIME.match(value):
            return datetime.fromisoformat(value).replace(tzinfo=timezone.utc)
        if len(value) < 11 or value[10] != "T" or " " in value:
            return None
        parsed = datetime.fromisoformat(value)
    except ValueError:
        return None
    return parsed if parsed.tzinfo is not None and parsed.utcoffset() is not None else None


def check_state(entry, name):
    def bad(message):
        return DataError("state", f"state.json: {name}: {message}")

    if "opened" in entry and parse_time(entry["opened"]) is None:
        raise bad("opened is not a time")
    if "archives" in entry:
        archives = entry["archives"]
        if not isinstance(archives, dict):
            raise bad("archives is not an object")
        for key, value in archives.items():
            if parse_time(value) is None:
                raise bad(f"time of {key} is not a time")
    if "rotations" in entry:
        rotations = entry["rotations"]
        if isinstance(rotations, bool) or not isinstance(rotations, int) or rotations < 0:
            raise bad("rotations is not a whole number")


def find_archives(logs_dir, name, naming):
    """The archives of a stream: dicts with stem, compressed, key (age order, bigger is newer for dated)."""
    found = []
    prefix = f"{name}.log."
    if not logs_dir.is_dir():
        return found
    for path in logs_dir.iterdir():
        file_name = path.name
        if not file_name.startswith(prefix) or not path.is_file():
            continue
        stem = file_name
        compressed = stem.endswith(".gz")
        if compressed:
            stem = stem[:-3]
        rest = stem[len(prefix):]
        if naming == "numbered":
            if not NUMBER.match(rest):
                continue
            key = int(rest)
        else:
            m = DAY.match(rest)
            if not m:
                continue
            try:
                date.fromisoformat(m.group(1))
            except ValueError:
                continue
            key = (m.group(1), int(m.group(2) or 1))
        found.append({"stem": stem, "old": file_name, "compressed": compressed, "key": key, "new": False})
    return found


def plan_stream(ctx, name, setting, entry, archives):
    log = streams.log_path(ctx.data, name)
    now = ctx.now
    reason = None
    size = 0
    if not log.is_file():
        what = "no log"
    else:
        size = log.stat().st_size
        if size == 0:
            what = "empty"
        elif ARGS_FORCE[0]:
            what, reason = "rotate (forced)", True
        elif setting["max_size"] is not None and size >= setting["max_size"]:
            what, reason = "rotate (size)", True
        else:
            what = "not due"
            if setting["max_age"] is not None:
                opened = parse_time(entry["opened"]) if "opened" in entry else first_line_time(log)
                if opened is not None and now - opened >= setting["max_age"]:
                    what, reason = "rotate (age)", True
    rotated = bool(reason)
    naming = setting["naming"]
    if rotated:
        if naming == "numbered":
            new = {"stem": None, "old": None, "compressed": False, "key": 0, "new": True}
        else:
            day = now.astimezone(timezone(setting["offset"])).date().isoformat()
            same = [a["key"][1] for a in archives if a["key"][0] == day]
            stem = f"{name}.log.{day}" + (f".{max(same) + 1}" if same else "")
            new = {"stem": stem, "old": None, "compressed": False,
                   "key": (day, max(same) + 1 if same else 1), "new": True}
        archives = archives + [new]
    if naming == "numbered":
        archives.sort(key=lambda a: a["key"])
    else:
        archives.sort(key=lambda a: a["key"], reverse=True)
    times = entry.get("archives", {})
    kept, removed = [], []
    for position, archive in enumerate(archives, 1):
        archive["time"] = ctx.stamp if archive["new"] else times.get(archive["old"])
        drop = position > setting["keep"]
        if not drop and setting["keep_days"] is not None and not archive["new"] and archive["time"] is not None:
            drop = now - parse_time(archive["time"]) >= timedelta(days=setting["keep_days"])
        (removed if drop else kept).append(archive)
    compressed_count = 0
    for position, archive in enumerate(kept, 1):
        archive["compress"] = position > setting["compress_after"] and not archive["compressed"]
        compressed_final = archive["compressed"] or archive["compress"]
        compressed_count += archive["compress"]
        stem = f"{name}.log.{position}" if naming == "numbered" else archive["stem"]
        archive["final"] = stem + (".gz" if compressed_final else "")
    return {"name": name, "what": what, "rotated": rotated, "kept": kept, "removed": removed,
            "compressed": compressed_count, "log": log}


def first_line_time(log):
    with log.open("rb") as f:
        line = f.readline()
    text = line.decode("utf-8", errors="replace").rstrip("\r\n")
    return parse_time(text.split(" ", 1)[0])


ARGS_FORCE = [False]


def run(ctx, args):
    from logkeep.cli import _stream

    ARGS_FORCE[0] = args.force
    requested = sorted(set(_stream(s) for s in args.streams))
    per_stream, defaults = policy.load(ctx.policy_path)
    doc = ctx.state
    active = set(streams.active(ctx.data))
    existing = active | set(per_stream)
    for name, entry in doc["streams"].items():
        if name in existing:
            check_state(entry, name)
    for name in requested:
        if name not in existing:
            raise Refused("unknown-stream", f"no stream {name}")
    names = requested if args.streams else sorted(existing)
    logs_dir = streams.logs_dir(ctx.data)
    plans = []
    for name in names:
        setting = policy.settings(per_stream, defaults, name)
        archives = find_archives(logs_dir, name, setting["naming"])
        seen = set()
        for archive in archives:
            if archive["stem"] in seen:
                raise DataError("archives", f"{name}: two archives in the place of {archive['stem']}")
            seen.add(archive["stem"])
        plans.append((plan_stream(ctx, name, setting, doc["streams"].get(name, {}), archives), setting))

    out = []
    rotated = removed = compressed = 0
    for plan, _ in plans:
        out.append(f"{plan['name']}: {plan['what']}")
        for archive in plan["kept"]:
            if archive["new"]:
                out.append(f"  new {archive['final']}")
            elif archive["final"] != archive["old"]:
                out.append(f"  {archive['final']} <- {archive['old']}")
            else:
                out.append(f"  {archive['final']}")
        for archive in plan["removed"]:
            out.append(f"  remove {archive['old']}")
        rotated += plan["rotated"]
        removed += len(plan["removed"])
        compressed += plan["compressed"]
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if args.dry_run:
        out.append("dry run: nothing written")
        return out

    deletes, writes, truncates = [], [], []
    for plan, _ in plans:
        for archive in plan["removed"]:
            deletes.append(logs_dir / archive["old"])
        for archive in plan["kept"]:
            if archive["new"]:
                data = plan["log"].read_bytes()
                truncates.append(plan["log"])
            elif archive["final"] != archive["old"]:
                data = (logs_dir / archive["old"]).read_bytes()
                deletes.append(logs_dir / archive["old"])
            else:
                continue
            if archive["compress"]:
                data = gzip.compress(data, mtime=0)
            writes.append((logs_dir / archive["final"], data))
    for path in deletes:
        path.unlink()
    for path, data in writes:
        path.write_bytes(data)
    for path in truncates:
        path.write_bytes(b"")

    from logkeep import state

    for plan, _ in plans:
        old = doc["streams"].get(plan["name"], {})
        entry = {}
        if plan["rotated"]:
            entry["opened"] = ctx.stamp
        elif "opened" in old:
            entry["opened"] = old["opened"]
        entry["rotations"] = old.get("rotations", 0) + (1 if plan["rotated"] else 0)
        entry["archives"] = {a["final"]: a["time"] for a in plan["kept"] if a["time"] is not None}
        doc["streams"][plan["name"]] = entry
    state.save(ctx.state_path, doc)
    return out
