                raise DataError("archives", f"{name}: two archives in the place of {archive['stem']}")
            seen.add(archive["stem"])
        plans.append((plan_stream(ctx, name, setting, doc["streams"].get(name, {}), archives), setting))

    out = []
    rotated = removed = compressed = 0
    for plan, _ in plans:
        out.append(f"{plan['name']}: {plan['what']}")
        for archive in plan["kept"]:
            if archive["new"]:
                out.append(f"  new {archive['final']}")
            elif archive["final"] != archive["old"]:
                out.append(f"  {archive['final']} <- {archive['old']}")
            else:
                out.append(f"  {archive['final']}")
        for archive in plan["removed"]:
            out.append(f"  remove {archive['old']}")
        rotated += plan["rotated"]
        removed += len(plan["removed"])
        compressed += plan["compressed"]
    out.append(f"{rotated} rotated, {removed} removed, {compressed} compressed")
    if args.dry_run:
        out.append("dry run: nothing written")
        return out

    deletes, writes, truncates = [], [], []
    for plan, _ in plans:
        for archive in plan["removed"]:
            deletes.append(logs_dir / archive["old"])
        for archive in plan["kept"]:
            if archive["new"]:
                data = plan["log"].read_bytes()
                truncates.append(plan["log"])
            elif archive["final"] != archive["old"]:
                data = (logs_dir / archive["old"]).read_bytes()
                deletes.append(logs_dir / archive["old"])
            else:
                continue
            if archive["compress"]:
                data = gzip.compress(data, mtime=0)
            writes.append((logs_dir / archive["final"], data))
    for path in deletes:
        path.unlink()
    for path, data in writes:
        path.write_bytes(data)
    for path in truncates:
        path.write_bytes(b"")

    from logkeep import state

    for plan, _ in plans:
        old = doc["streams"].get(plan["name"], {})
        entry = {}
        if plan["rotated"]:
            entry["opened"] = ctx.stamp
        elif "opened" in old:
            entry["opened"] = old["opened"]
        entry["rotations"] = old.get("rotations", 0) + (1 if plan["rotated"] else 0)
        entry["archives"] = {a["final"]: a["time"] for a in plan["kept"] if a["time"] is not None}
        doc["streams"][plan["name"]] = entry
    state.save(ctx.state_path, doc)
    return out
